document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("date-shift-form"),t=document.getElementById("date-shift-result");e.addEventListener("submit",function(e){e.preventDefault();const n=new Date(document.getElementById("base-date").value),a=parseInt(document.getElementById("day-offset").value,10);if(isNaN(n)||isNaN(a))return t.textContent="Please enter valid data.",void 0;const d=new Date(n);d.setDate(n.getDate()+a);const o=d.toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric"}),s=d.toISOString().split("T")[0],l=1===Math.abs(a)?"day":"days";let i;i=a>0?`in ${a} ${l}`:a<0?`${Math.abs(a)} ${l} ago`:"today (no change)",t.innerHTML=`\n      <b>Result:</b><br>\n      The date <b>${i}</b> will be:<br>\n      <b>${o}</b><br>\n      <small>(${s})</small>\n    `})});